/**
 * The learned local capability snapshot.
 *
 * The plugin used to bundle a static pi-ai / models.dev snapshot; most relay
 * providers publish neither reasoning ladders nor context windows, so that
 * snapshot aged quickly and had to be regenerated by hand. It is gone: the
 * replacement is this store, seeded by the settings page's "verify all
 * models" run (public catalogs plus the checker model the user picked) and
 * persisted in `$DSH_HOME/dsh-model-visibility/learned.json`.
 *
 * A verified fact is keyed by *normalized model id* rather than by provider,
 * so the same model served under a second route, or a `:free` variant its
 * relay invents later, resolves to the cached row without another sweep.
 * Fields mirror the provider schema where possible so writes into provider
 * settings and learned facts stay one transform apart.
 *
 * The Host reads the file synchronously and re-reads it when the mtime
 * changes, following the same pattern as `lib/model-overrides.js`: a hand
 * edit of `learned.json` is enough to apply a fix.
 *
 * @module lib/learned-catalog
 */
import fs from 'node:fs'
import os from 'node:os'
import path from 'node:path'

import { MODEL_KINDS } from './capability-catalog.js'
import { modelIdVariants } from './model-id.js'

import { sanitizeEfforts, sanitizeModalities, text } from './model-overrides.js'

/** Absolute path of the learned snapshot below `$DSH_HOME`. */
export function learnedFile(home) {
  const base = home || process.env.DSH_HOME || path.join(os.homedir(), '.dsh')
  return path.join(base, 'dsh-model-visibility', 'learned.json')
}

/**
 * Normalize one verified fact into the store's detached record.
 * @param input - a check result entry, possibly malformed.
 * @returns `{ id, idSource, entry }` or undefined when nothing usable remains.
 */
export function sanitizeLearned(input) {
  if (input === null || typeof input !== 'object') return undefined
  const id =
    text(input.id) ??
    (input.provider !== undefined && input.model !== undefined
      ? text(input.model)
      : undefined)
  if (id === undefined || text(id) === '') return undefined
  const entry = {}
  if (typeof input.type === 'string' && MODEL_KINDS.includes(input.type)) entry.type = input.type
  const inputModalities = sanitizeModalities(input.input)
  if (inputModalities !== undefined) entry.input = inputModalities
  const output = sanitizeModalities(input.output)
  if (output !== undefined) entry.output = output
  if (Number.isSafeInteger(input.contextWindow) && input.contextWindow > 0) {
    entry.contextWindow = input.contextWindow
  }
  if (Number.isSafeInteger(input.maxTokens) && input.maxTokens > 0) entry.maxTokens = input.maxTokens
  const efforts = sanitizeEfforts(input.reasoningEfforts ?? input.efforts)
  if (efforts !== undefined) entry.reasoningEfforts = efforts
  const defaultEffort = text(input.defaultEffort)
  if (defaultEffort !== undefined) entry.defaultEffort = defaultEffort
  if (typeof input.reasoning === 'boolean') entry.reasoning = input.reasoning
  const provider = text(input.provider)
  if (provider !== undefined) entry.provider = provider
  const declared =
    entry.type !== undefined ||
    entry.input !== undefined ||
    entry.output !== undefined ||
    entry.contextWindow !== undefined ||
    entry.maxTokens !== undefined ||
    entry.reasoningEfforts !== undefined ||
    entry.reasoning !== undefined
  if (!declared) return undefined
  const origins = Array.isArray(input.origins)
    ? [...new Set(input.origins.filter((item) => item === 'public' || item === 'checker' || item === 'manual'))]
    : []
  const verifiedAt = Number(input.verifiedAt)
  return {
    id,
    idSource: typeof input.idSource === 'string' ? input.idSource : 'id',
    entry: {
      ...entry,
      verifiedAt: Number.isSafeInteger(verifiedAt) && verifiedAt > 0 ? verifiedAt : Date.now(),
      ...(origins.length > 0 ? { origins } : { origins: [] }),
      ...(input.checker !== null && typeof input.checker === 'object'
        ? { checker: input.checker }
        : {}),
    },
  }
}

/**
 * A file-backed store of verified capability facts, keyed by normalized id.
 *
 * @param options - `{ file?, home?, logger?, now? }`.
 * @returns `{ file, meta, list, get, upsertEntries, invalidate }`.
 */
export function createLearnedCatalog(options = {}) {
  const file = options.file || learnedFile(options.home)
  const logger = options.logger ?? console
  const now = typeof options.now === 'function' ? options.now : Date.now
  /** `variants -> canonical id`, rebuilt whenever the file changes. */
  let index = new Map()
  /** canonical id -> detached record (entry keys, provider shape). */
  let records = new Map()
  let store = null
  let loaded = false
  let loadedMtime = -Infinity

  const warn = (message, error) => {
    if (typeof logger.warn === 'function') {
      logger.warn(message)
      if (error !== undefined) logger.warn(error)
    }
  }

  const mtimeOf = () => {
    try {
      return fs.statSync(file).mtimeMs
    } catch (_error) {
      return -Infinity
    }
  }

  const buildIndex = () => {
    index = new Map()
    for (const [canonical, record] of records) {
      for (const variant of modelIdVariants(record.id)) {
        if (!index.has(variant)) index.set(variant, canonical)
      }
      if (!index.has(canonical)) index.set(canonical, canonical)
    }
  }

  const readRecord = (raw) => {
    const sanitized = sanitizeLearned(raw)
    if (sanitized === undefined) return undefined
    const record = sanitized.entry
    return { id: sanitized.id, ...record }
  }

  const load = (force = false) => {
    const mtime = mtimeOf()
    if (!force && loaded && mtime === loadedMtime) return
    loaded = true
    loadedMtime = mtime
    records = new Map()
    store = null
    if (mtime === -Infinity) {
      buildIndex()
      return
    }
    try {
      const parsed = JSON.parse(fs.readFileSync(file, 'utf8'))
      store = parsed !== null && typeof parsed === 'object' ? parsed : null
      const source =
        store !== null && store.models !== null && typeof store.models === 'object'
          ? store.models
          : null
      if (source !== null) {
        for (const [key, raw] of Object.entries(source)) {
          const record = readRecord(raw)
          if (record !== undefined && !records.has(key)) records.set(key, record)
        }
      }
    } catch (error) {
      warn('model-visibility: could not read the learned snapshot; starting empty', error)
      store = null
    }
    buildIndex()
  }

  const persistLocked = () => {
    fs.mkdirSync(path.dirname(file), { recursive: true })
    const body = {
      version: 1,
      ...(store?.checker !== undefined ? { checker: store.checker } : {}),
      updatedAt: now(),
      models: Object.fromEntries([...records.entries()].map(([key, record]) => [key, record])),
    }
    const temp = `${file}.${process.pid}.tmp`
    fs.writeFileSync(temp, `${JSON.stringify(body, null, 2)}\n`)
    fs.renameSync(temp, file)
    loadedMtime = mtimeOf()
  }

  /** Footer facts for the settings page (full file read). */
  const meta = () => {
    load()
    return {
      file,
      models: records.size,
      updatedAt:
        store !== null && Number.isSafeInteger(store.updatedAt) ? store.updatedAt : undefined,
      checker: store !== null && store.checker !== null && typeof store.checker === 'object' ? store.checker : undefined,
    }
  }

  /** Detached copies of every fact, in normalized-key order. */
  const list = () => {
    load()
    return [...records.values()].map((record) => ({ ...record }))
  }

  /** One verified fact for any spelling of the model id, or undefined. */
  const get = (value) => {
    if (typeof value !== 'string') return undefined
    const variants = modelIdVariants(value)
    if (variants.length === 0) return undefined
    load()
    let fallback
    for (const variant of variants) {
      const canonical = index.get(variant)
      if (canonical === undefined) {
        if (fallback === undefined && records.has(variant)) fallback = records.get(variant)
        continue
      }
      const record = records.get(canonical)
      if (record === undefined) continue
      return { ...record }
    }
    return fallback === undefined ? undefined : { ...fallback }
  }

  /**
   * Merge verified facts in; a newer verification wins field by field.
   *
   * The same model may arrive twice (its id from one relay, a corrected id
   * from the checker), so records merge instead of replacing. An older batch
   * may fill fields the newer batch did not know, but must never replace a
   * newer declaration or make it look freshly verified.
   * @param inputs - check results, each `{ id | provider+model, …facts }`.
   * @param extra - provenance for the whole call: `verifiedAt`, `origins`,
   *   `checker`. `origins` is merged into each record so a later public-only
   *   pass appends `public` next to an earlier `checker` instead of replacing
   *   it (which is what made "publicOnly: 0" look like a missing source).
   */
  const upsertEntries = (inputs, extra = {}) => {
    // A verify sweep now flushes one array of facts per batch instead of one
    // call per model. Reloading by force for every call forced a full file read
    // and a full rewrite per model (199 reads + 199 writes for 200 models).
    load(true)
    const source = Array.isArray(inputs) ? inputs : [inputs]
    let changed = false
    for (const raw of source) {
      const sanitized = sanitizeLearned(raw)
      if (sanitized === undefined) continue
      // Call-side provenance beats the entry's own stamps: the orchestrator
      // knows the run that produced the fact. An entry that carries its own
      // `origins` keeps them, so a public-only row stays `['public']`.
      const provenance = {}
      if (extra?.verifiedAt !== undefined) provenance.verifiedAt = extra.verifiedAt
      if (extra?.origins !== undefined && raw?.origins === undefined) provenance.origins = extra.origins
      if (extra?.checker !== undefined) provenance.checker = extra.checker
      const record = { provider: raw?.provider, ...sanitized.entry, ...provenance, id: sanitized.id }
      const key = modelIdVariants(record.id)[0] ?? sanitized.id
      const existing = records.get(key)
      if (existing === undefined) {
        records.set(key, record)
        changed = true
        continue
      }
      const next = { ...existing }
      const incomingIsNewer = (record.verifiedAt ?? 0) >= (existing.verifiedAt ?? 0)
      for (const [field, value] of Object.entries(record)) {
        if (value === undefined || value === null) continue
        if (!incomingIsNewer && existing[field] !== undefined && field !== 'origins') continue
        if (field === 'verifiedAt') {
          next.verifiedAt = Math.max(existing.verifiedAt ?? 0, value)
          continue
        }
        if (field === 'origins' && Array.isArray(existing.origins)) {
          const union = [...new Set([...existing.origins, ...value])]
          if (JSON.stringify(union) === JSON.stringify(existing.origins)) continue
          next.origins = union
          continue
        }
        next[field] = value
      }
      if (JSON.stringify(next) !== JSON.stringify(existing)) {
        records.set(key, next)
        changed = true
      }
    }
    if (changed) {
      buildIndex()
      try {
        persistLocked()
      } catch (error) {
        warn('model-visibility: could not write the learned snapshot', error)
      }
    }
  }

  /** Forget the memoized copy; the next read consults the file again. */
  const invalidate = () => {
    loaded = false
    loadedMtime = -Infinity
  }

  return { file, meta, list, get, upsertEntries, invalidate }
}
